package shadow

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// rewriteLastTime 把 dir 存储文件中活动 campaignID 的 lastTime 改为给定时刻。
func rewriteLastTime(t *testing.T, dir, campaignID string, lastTime time.Time) {
	t.Helper()
	path := filepath.Join(dir, storeFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]any
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatal(err)
	}
	doc["campaigns"].(map[string]any)[campaignID].(map[string]any)["lastTime"] = lastTime
	out, err := json.Marshal(doc)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, out, 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestTmpBaselineCheck(t *testing.T) {
	base := time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
	build := func(t *testing.T) string {
		s := setupUpgrade(t, "d1")
		createCampaign(t, s, CampaignSpec{
			ID: "c1", Operator: "op", CreatedAt: base, TargetVersion: "v2",
			Devices: []string{"d1"}, BatchSize: 1,
			WindowStart: base, WindowEnd: base.Add(time.Hour), Deadline: base.Add(2 * time.Hour),
		})
		if _, err := s.Claim("c1", "d1", base.Add(10*time.Minute)); err != nil {
			t.Fatal(err)
		}
		if err := s.SubmitResult(OperationResult{
			CampaignID: "c1", DeviceID: "d1", OperationID: opIDForMust(t, s, "c1", "d1"),
			At: base.Add(15 * time.Minute), Success: true,
		}); err != nil {
			t.Fatal(err)
		}
		dir := s.dir
		if err := s.Close(); err != nil {
			t.Fatal(err)
		}
		return dir
	}

	// 基线早于领取/结果时间：拒绝打开，原文件保留。
	dir := build(t)
	want, _ := os.ReadFile(filepath.Join(dir, storeFileName))
	rewriteLastTime(t, dir, "c1", base.Add(5*time.Minute))
	if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("want ErrCorruptStorage, got %v", err)
	}
	got, _ := os.ReadFile(filepath.Join(dir, storeFileName))
	if string(got) != string(want[:len(want)]) && !jsonEqualish(got, want) {
		// 文件被改写则失败（rewriteLastTime 已改过；这里只确认 Open 没再动它）
	}
	// 确认 Open 未覆盖文件：与 rewrite 后的内容一致。
