	if err != nil {
		t.Fatalf("later baseline should open: %v", err)
	}
	// 重开后仍按基线拒绝倒退。
	if _, err := s2.Claim("c1", "d1", base.Add(20*time.Minute)); !errors.Is(err, ErrTimeRegression) {
		t.Fatalf("want ErrTimeRegression, got %v", err)
	}
	s2.Close()

	// 基线恰好等于最晚记录（相等合法，含时区差异）：正常打开。
	dir3 := build(t)
	loc := time.FixedZone("x", 8*3600)
	rewriteLastTime(t, dir3, "c1", base.Add(15*time.Minute).In(loc))
	if _, err := Open(dir3); err != nil {
		t.Fatalf("equal instant in another zone should open: %v", err)
	}
}

func opIDForMust(t *testing.T, s *Store, cid, did string) string {
	t.Helper()
	v, err := s.GetCampaign(cid)
	if err != nil {
		t.Fatal(err)
	}
	for _, d := range v.Devices {
		if d.DeviceID == did {
			return d.DownloadID
		}
	}
	t.Fatal("device not found")
	return ""
}

